 var right=new DockPanel{Background=new SolidColorBrush(Color.FromRgb(59,62,65))};var footer=new Border{Height=28,Background=new SolidColorBrush(Color.FromRgb(228,229,231)),Child=status};DockPanel.SetDock(footer,Dock.Bottom);right.Children.Add(footer);var historyPanel=new Expander{Header="历史结果",IsExpanded=false,Foreground=System.Windows.Media.Brushes.White};historyPanel.Content=new DataGrid{IsReadOnly=true,AutoGenerateColumns=true,ItemsSource=history,CanUserAddRows=false,Height=195};DockPanel.SetDock(historyPanel,Dock.Bottom);right.Children.Add(historyPanel);var resultTabs=new TabControl{Tag="ImageBinaryResultTabs",Background=new SolidColorBrush(Color.FromRgb(59,62,65))};var imagePanel=new DockPanel();var view=roi.ReplacePane(1,right);if(view is DockPanel viewDock&&viewDock.Children[0] is FrameworkElement zoom){viewDock.Children.Remove(zoom);var imageBar=new Grid{Height=40};imageBar.ColumnDefinitions.Add(new());imageBar.ColumnDefinitions.Add(new(){Width=new(160)});images.HorizontalAlignment=HorizontalAlignment.Left;images.Margin=new(8,3,0,3);imageBar.Children.Add(images);Grid.SetColumn(zoom,1);imageBar.Children.Add(zoom);DockPanel.SetDock(imageBar,Dock.Top);viewDock.Children.Insert(0,imageBar);}imagePanel.Children.Add(view);resultTabs.Items.Add(new TabItem{Header="图像",Content=imagePanel});resultTabs.Items.Add(new TabItem{Header="模块结果",Content=resultGrid});right.Children.Add(resultTabs);images.ItemsSource=new[]{"输入图像"};images.SelectedIndex=0;images.SelectionChanged+=(_,_)=>ShowSelectedImage();Body.Content=roi;ready=true;roi.DrawingStarted+=(_,_)=>{images.SelectedIndex=0;roi.SetRuntimeRegionPreview(null);roi.SetImage(InputImage());};roi.GeometryCommitted+=(_,_)=>CommitLive();Closed+=(_,_)=>closed=true;
