 static TextBlock Heading(string text)=>new(){Text=text,FontWeight=FontWeights.Bold,Margin=new(0,8,0,6)};
 static DockPanel LabelRow(string label,FrameworkElement control){var row=new DockPanel{MinHeight=32};row.Children.Add(new TextBlock{Text=label,Width=89,VerticalAlignment=VerticalAlignment.Center});row.Children.Add(control);return row;}
 FrameworkElement InputRow(string label,string port){var button=new Button{Content=context.InputLabel?.Invoke(port)??"------",Tag="ImageBinaryInput:"+port,HorizontalContentAlignment=HorizontalAlignment.Left,IsEnabled=context.EditInput is not null};button.Click+=(_,_)=>{try{context.EditInput?.Invoke(port,this);button.Content=context.InputLabel?.Invoke(port)??"------";LastResult=null;images.ItemsSource=new[]{"输入图像"};images.SelectedIndex=0;roi.SetImage(InputImage());}catch(Exception e){status.Text=e.Message;}};inputButtons.Add(button);return LabelRow(label,button);}
 FrameworkElement BuildRunParameters(){
  parameterFields.Clear();var panel=new StackPanel{Margin=new(32,1,32,0)};
  var modes=new ComboBox{Tag="ImageBinaryMode",Height=30};
  foreach(var pair in new[]{("硬阈值",1),("均值",2),("高斯",3),("Sauvola",8),("自动阈值",4)})modes.Items.Add(new ComboBoxItem{Content=pair.Item1,Tag=pair.Item2});
  modes.SelectedItem=modes.Items.OfType<ComboBoxItem>().FirstOrDefault(i=>Equals(i.Tag,values["BinaryType"].GetInt32()));
  modes.SelectionChanged+=(_,_)=>{if(modes.SelectedItem is ComboBoxItem item){values["BinaryType"]=JsonSerializer.SerializeToElement((int)item.Tag);if(parameterTabs.Items.Count>1)((TabItem)parameterTabs.Items[1]).Content=BuildRunParameters();CommitLive();}};
  panel.Children.Add(LabelRow("二值化类型",modes));
  var outside=new ComboBox{ItemsSource=new[]{"置黑","保留原图"},SelectedIndex=values["NonROIPrcType"].GetInt32(),Height=30,Tag="ImageBinaryOutside"};
  outside.SelectionChanged+=(_,_)=>{values["NonROIPrcType"]=JsonSerializer.SerializeToElement(outside.SelectedIndex);CommitLive();};panel.Children.Add(LabelRow("ROI外处理",outside));
  ParameterDescriptor Descriptor(string name)=>new ImageBinaryPlugin().Descriptor.Parameters.Single(p=>p.Name==name);
  void Integer(string name,string label){var descriptor=Descriptor(name);var field=new RoiNumericField(values[name].GetInt32(),descriptor.Minimum??-30000,descriptor.Maximum??30000,true);field.ValueCommitted+=(_,_)=>CommitNumeric(name,field.Input.Text,true);field.Input.Tag="ImageBinaryField:"+name;parameterFields[name]=field;panel.Children.Add(LabelRow(label,field));}
  void Number(string name,string label){var descriptor=Descriptor(name);double increment=name=="SauvolaAdjustCoef"?.001:.1;var field=new RoiNumericField(values[name].GetDouble(),descriptor.Minimum??-30000,descriptor.Maximum??30000,false,increment);field.ValueCommitted+=(_,_)=>CommitNumeric(name,field.Input.Text,false);field.Input.Tag="ImageBinaryField:"+name;parameterFields[name]=field;panel.Children.Add(LabelRow(label,field));}
  void Enumeration(string name,string label,string[] choices){var combo=new ComboBox{Tag="ImageBinaryField:"+name,Height=30,ItemsSource=choices,SelectedIndex=values[name].GetInt32()};combo.SelectionChanged+=(_,_)=>{if(combo.SelectedIndex>=0){values[name]=JsonSerializer.SerializeToElement(combo.SelectedIndex);CommitLive();}};panel.Children.Add(LabelRow(label,combo));}
  switch(values["BinaryType"].GetInt32()){
   case 1:Integer("LowThreshold","低阈值");Integer("HighThreshold","高阈值");break;
   case 2:Integer("KernelWidth","滤波核宽度");Integer("KernelHeight","滤波核高度");Enumeration("CompareType","比较类型",["大于等于","小于等于","等于","不等于"]);Integer("ThresholdOffset","阈值偏移量");break;
   case 3:Integer("GaussKernelSize","高斯滤波核");Number("GaussSigma","高斯标准差");Enumeration("CompareType","比较类型",["大于等于","小于等于","等于","不等于"]);Integer("ThresholdOffset","阈值偏移量");break;
   case 8:Number("SauvolaAdjustCoef","Sauvola调整系数");Number("SauvolaRange","Sauvola范围");Enumeration("SauvolaSegType","分割类型",["暗目标","亮目标"]);Integer("SauvolaWinWidth","滤波核宽度");Integer("SauvolaWinHeight","滤波核高度");break;
  }
  return panel;
 }
 void CommitNumeric(string name,string text,bool integer){double value;if(integer){if(!int.TryParse(text,out var parsed))return;value=parsed;}else if(!double.TryParse(text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out value)||!double.IsFinite(value))return;var descriptor=new ImageBinaryPlugin().Descriptor.Parameters.Single(p=>p.Name==name);if(descriptor.Minimum is double min&&value<min||descriptor.Maximum is double max&&value>max){status.Text=$"{name} 必须在 {descriptor.Minimum} 到 {descriptor.Maximum} 范围内。";return;}values[name]=integer?JsonSerializer.SerializeToElement((int)value):JsonSerializer.SerializeToElement(value);CommitLive();}
 FrameworkElement BuildDisplayParameters(){var panel=new StackPanel{Margin=new(32,1,32,0)};foreach(var pair in displayStyles){var key=pair.Key;var editor=new RoiDisplayStyleEditor(key switch{"ROI"=>"检测区域","Annular"=>"环形区域",_=>"屏蔽区域"},pair.Value){IsEnabled=context.ApplyDisplayStyles is not null};editor.Changed+=style=>{displayStyles[key]=style;context.ApplyDisplayStyles?.Invoke(RoiDisplayStyles.Snapshot(displayStyles));roi.SetDisplayStyles(displayStyles,LastResult?.Status is NodeRunStatus.Failed or NodeRunStatus.NoMatch);};panel.Children.Add(editor);}return panel;}
 void CommitLive(){if(!ready||applying||context.Session?.IsBusy==true)return;try{Apply();}catch(Exception e){status.Text=e.Message;}}
 void Apply(){if(applying)return;applying=true;try{ReadRegionInputs();foreach(var field in parameterFields){var descriptor=new ImageBinaryPlugin().Descriptor.Parameters.Single(p=>p.Name==field.Key);if(descriptor.Kind==ParameterKind.Integer){if(!int.TryParse(field.Value.Input.Text,System.Globalization.NumberStyles.Integer,System.Globalization.CultureInfo.InvariantCulture,out var integer)||descriptor.Minimum is double min&&integer<min||descriptor.Maximum is double max&&integer>max)throw new InvalidDataException($"{field.Key} 必须是 {descriptor.Minimum} 到 {descriptor.Maximum} 范围内的整数。");values[field.Key]=JsonSerializer.SerializeToElement(integer);}else{if(!double.TryParse(field.Value.Input.Text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var number)||!double.IsFinite(number)||descriptor.Minimum is double min&&number<min||descriptor.Maximum is double max&&number>max)throw new InvalidDataException($"{field.Key} 超出原厂参数范围 {descriptor.Minimum} 到 {descriptor.Maximum}。");values[field.Key]=JsonSerializer.SerializeToElement(number);}}roi.CommitPending();RoiGeometry.ValidateForEditor(roi.Regions,ImageBinaryPlugin.RoiCapabilities);if(values["LowThreshold"].GetInt32()>values["HighThreshold"].GetInt32())throw new InvalidDataException("低阈值不能大于高阈值。");if(context.ApplyConfigurationChange is {} change)change(values,roi.Regions,pendingClears.ToArray());else (context.ApplyConfiguration??throw new InvalidOperationException("宿主未接入ROI配置写入。"))(values,roi.Regions);pendingClears.Clear();}finally{applying=false;}}
 void Busy(bool value){run.IsEnabled=repeat.IsEnabled=!value;repeat.Visibility=value?Visibility.Collapsed:Visibility.Visible;stop.Visibility=value?Visibility.Visible:Visibility.Collapsed;parameterTabs.IsEnabled=!value;foreach(var button in inputButtons)button.IsEnabled=!value&&context.EditInput is not null;}
 void Present(NodeRunRecord result){if(closed)return;LastResult=result;roi.SetDisplayStyles(displayStyles,result.Status is NodeRunStatus.Failed or NodeRunStatus.NoMatch);history.Add(new(++executionIndex,DateTime.Now.ToString("HH:mm:ss.fff"),result.Status+" · "+result.Message));if(history.Count>256)history.RemoveAt(0);if(context.Session?.State==ToolDebugState.RunningContinuous&&presentationClock.ElapsedMilliseconds<100)return;presentationClock.Restart();showing=true;images.ItemsSource=new[]{"输入图像"}.Concat(result.Outputs.Where(p=>p.Value.Kind==DataKind.GrayImage).Select(p=>p.Key=="Image"?"输出图像":p.Key)).ToArray();images.SelectedIndex=result.Outputs.ContainsKey("Image")?1:0;showing=false;resultGrid.ItemsSource=result.Outputs.Select(p=>new{名称=p.Key,值=p.Value.Value is VisionCore.GrayImage image?$"{image.Width} × {image.Height}":p.Value.Value.ToString()}).ToArray();status.Text=result.Status+" · "+result.Message;ShowSelectedImage();}
 void ShowSelectedImage(){if(showing)return;string key=images.SelectedItem as string??"输入图像";roi.SetRuntimeRegionPreview(null);if(key=="输入图像")roi.SetImage(InputImage());else if(LastResult?.Outputs.TryGetValue(key=="输出图像"?"Image":key,out var image)==true){roi.SetImage(image.As<VisionCore.GrayImage>());if(values["RoiSelect"].GetInt32()==1||values["ExternRoiSelect"].GetInt32()==1||values["Assist0"].GetBoolean()){try{var inputs=new Dictionary<string,PortValue>();foreach(var port in new ImageBinaryPlugin().Descriptor.Inputs){if(context.PreviewInput?.Invoke(port.Name) is {} value)inputs[port.Name]=value;}var input=InputImage()??image.As<VisionCore.GrayImage>();var execution=new ModuleExecutionContext(context.Node.Id,context.BaseDirectory,inputs,values,roi.Regions);roi.SetRuntimeRegionPreview(BinaryRegionResolver.Resolve(execution,input.Width,input.Height),BinaryRegionResolver.Fixture(execution));}catch(Exception error){roi.SetRuntimeRegionPreview([]);status.Text="区域预览："+error.Message;}}}}
 public async Task RunAsync(){Busy(true);try{Apply();Present(await context.Run(values));}catch(Exception e){status.Text=e.Message;}finally{Busy(false);}}
 public async Task RunContinuousAsync(){if(context.Session is not {} session){status.Text="调试会话不可用。";return;}Busy(true);try{Apply();await session.RunContinuousAsync(()=>values,Present);}catch(OperationCanceledException){}catch(Exception e){status.Text=e.Message;}finally{Busy(false);}}
